import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_packages(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            tf = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], tf)
                pkgs[key] = pkg['resolvedVersion']
        result[name] = pkgs
    return result

b = get_packages(baseline)
a = get_packages(after)

changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            changes.append(f'  {proj}: {key[0]} ({key[1]}): {bv} -> {av}')

if changes:
    print('VERSION CHANGES:')
    for c in changes: print(c)
else:
    print('No version changes - conversion is version-neutral for resolved versions')

# Show aligned versions (where we used highest)
print()
print('Note: Source version changes (aligned to highest):')
